import React from "react";
import { AbsoluteFill, Series, Video, staticFile } from "remotion";

// Import the manifest generated by your Python script
import scenes from "./remotion_manifest.json";

export const FullEpisode: React.FC = () => {
  return (
    <AbsoluteFill style={{ backgroundColor: "black" }}>
      {/* 
        The <Audio> tag has been removed to prevent the "double sound" echo. 
        Your bash script (Step 7) is already multiplexing voice_over.mp3, 
        so Remotion should only render the silent video sequence.
      */}

      <Series>
        {scenes.map((scene: any) => {
          // Base audio duration mapped by Faster-Whisper
          const durationInFrames = Math.round(scene.durationSec * 30);
          
          // Recalculate playback rate to fit the original timeline perfectly without overlap
          const originalVideoFrames = scene.videoDurationSec * 30;
          const playbackRate = originalVideoFrames / durationInFrames;

          return (
            <Series.Sequence 
              key={scene.scene_id} 
              durationInFrames={durationInFrames}
            >
              <Video 
                src={staticFile(`Scene${String(scene.scene_id).padStart(2, '0')}.mp4`)}
                playbackRate={playbackRate}
                volume={0} // Ensure video assets are strictly muted
                style={{ width: "100%", height: "100%", objectFit: "cover" }}
              />
            </Series.Sequence>
          );
        })}
      </Series>
    </AbsoluteFill>
  );
};
